    i_a_u: { tr: 'i – a – u ailesi', es: 'Familia i – a – u', tipTr: 'Ünlü sırayla i → a → u olur: drink – drank – drunk, swim – swam – swum, begin – began – begun.', tipEs: 'La vocal cambia i → a → u: drink – drank – drunk, swim – swam – swum.' },
    ew_own: { tr: '-ew / -own ailesi', es: 'Familia -ew / -own', tipTr: 'V2 -ew, V3 -own/-awn: know – knew – known, grow – grew – grown, fly – flew – flown.', tipEs: 'V2 en -ew, V3 en -own/-awn: know – knew – known, fly – flew – flown.' },
