    ore_orn: { tr: '-ore / -orn ailesi', es: 'Familia -ore / -orn', tipTr: 'wear – wore – worn, tear – tore – torn: V2 -ore, V3 -orn.', tipEs: 'wear – wore – worn, tear – tore – torn: V2 en -ore, V3 en -orn.' },
    ABC_en: { tr: 'Üçü farklı, V3 -en/-n', es: 'Las tres distintas, V3 en -en/-n', tipTr: 'Hepsi farklı ama V3 -en/-n ile biter: eat – ate – eaten, take – took – taken, see – saw – seen.', tipEs: 'Todas distintas, pero la V3 termina en -en/-n: eat – ate – eaten, see – saw – seen.' },
    ABC_other: { tr: 'Kalıba uymayanlar', es: 'Sin patrón', tipTr: 'Bunlar tek tek ezberlenir — en sık kullanılanlar oldukları için çabuk oturur: be – was – been, go – went – gone.', tipEs: 'Se memorizan uno a uno — son muy frecuentes y se fijan rápido: be – was – been, go – went – gone.' }
