  "swim": { lvl: 2, fam: "i_a_u", def: "to move through water using your arms and legs", ex: "We swam in the sea every morning.", exTr: "Her sabah denizde yüzdük.", ex3: "I have never swum in a lake.", ex3Tr: "Hiç gölde yüzmedim." },
