const PV_GROUPS = [
  { p: "up", title: "UP", tr: "tamamen bitirme · artış · yukarı", es: "completar · aumentar · arriba", tip: "UP çoğu zaman bir işi 'tamamen, sonuna kadar' yapmayı (eat up = hepsini yemek, use up = tüketmek) ya da artışı/yukarıyı (speed up = hızlanmak) anlatır." },
  { p: "down", title: "DOWN", tr: "aşağı · azalma · kâğıda dökme", es: "abajo · disminuir · anotar", tip: "DOWN aşağı inmeyi ya da azalmayı, yavaşlamayı anlatır (sit down = oturmak, slow down = yavaşlamak). Bazen de 'kâğıda dökmek' ya da 'çöküp durmak' demektir (write down = not etmek, break down = bozulmak)." },
  { p: "out", title: "OUT", tr: "dışarı · ortaya çıkarma · çözme", es: "fuera · descubrir · resolver", tip: "OUT içeriden dışarı çıkmayı anlatır (go out = dışarı çıkmak, eat out = dışarıda yemek). Ayrıca saklı ya da belirsiz olanı açığa çıkarmayı anlatır (find out = öğrenmek, figure out = çözmek)." },
  { p: "off", title: "OFF", tr: "ayrılma · durdurma · iptal", es: "separar · apagar · cancelar", tip: "OFF bir şeyden ayrılmayı, kopmayı ya da durdurmayı anlatır (take off = çıkarmak / havalanmak, turn off = kapatmak). Planlarla kullanılınca iptal ya da erteleme demektir (call off = iptal etmek, put off = ertelemek)." },
  { p: "on", title: "ON", tr: "devam · üstünde · çalışır halde", es: "continuar · encima · encendido", tip: "ON çoğu zaman 'devam etme' anlamı taşır (go on = devam etmek, hold on = beklemek). Ayrıca bir şeyin üstte ya da çalışır halde olmasını anlatır (put on = giymek, turn on = açmak)." },
  { p: "in", title: "IN / INTO", tr: "içeri · katılma · dönüşme", es: "dentro · participar · convertirse", tip: "IN içeri girmeyi ya da bir şeyin içine katılmayı anlatır (come in = içeri girmek, fill in = doldurmak). INTO ise bir şeyin içine girmeyi ya da başka bir şeye dönüşmeyi anlatır (look into = araştırmak, turn into = dönüşmek)." },
  { p: "over", title: "OVER", tr: "baştan sona · öbür yana · devrilme", es: "repasar · al otro lado · volcar", tip: "OVER bir şeyin üzerinden baştan sona geçmeyi anlatır (go over = gözden geçirmek, think over = iyice düşünmek). Bir yandan öbür yana geçmeyi ya da devrilmeyi de anlatır (come over = bize gelmek, knock over = devirmek)." },
  { p: "back", title: "BACK", tr: "geri dönüş · eski yer · karşılık", es: "volver · devolver · responder", tip: "BACK bir şeyin ya da birinin eski yerine, eski haline dönmesini anlatır (come back = geri gelmek, give back = geri vermek). Karşılık vermek için de kullanılır (call back = geri aramak, pay back = borcunu ödemek)." },
  { p: "away", title: "AWAY", tr: "uzaklaşma · ortadan kaldırma · yok olma", es: "alejarse · deshacerse · desaparecer", tip: "AWAY uzaklaşmayı ve bir şeyi gözden, ortadan kaldırmayı anlatır (run away = kaçmak, throw away = çöpe atmak). Yavaş yavaş yok olmayı da anlatabilir (go away = geçmek, pass away = vefat etmek)." },
  { p: "around", title: "AROUND / ABOUT", tr: "etrafta dolaşma · dönme · meydana gelme", es: "alrededor · girar · ocurrir", tip: "AROUND belli bir hedef olmadan etrafta dolaşmayı ya da yön değiştirip dönmeyi anlatır (look around = etrafa bakmak, turn around = arkasına dönmek). ABOUT ise bir şeyin meydana gelmesini anlatır (bring about = yol açmak, come about = ortaya çıkmak)." },
  { p: "other", title: "Diğer / 3 kelimeli", tr: "edat mantığı dışı · 3 kelimeli kalıplar", es: "sin lógica fija · verbos de tres palabras", tip: "Bu fiillerin anlamı edattan tahmin edilemez ya da üç kelimeden oluşur; onları tek parça bir kalıp gibi ezberle (look after = bakmak, run out of = tükenmek). Üç kelimelilerden sonra isim ya da -ing gelir (look forward to seeing you = seni görmeyi dört gözle beklemek)." },
];

